export interface BoxSelectorProps<T> extends ActivatableProps {
	icon?: string;
	items: {
		name: string;
		description: string;
		value: T;
	}[];

	title?: string;

	selectedValue: Accessor<T>;
	setSelectedValue: (value: T) => void;
	bgImage?: string;
	bgImagePositionX?: number;
	bgImagePositionY?: number;
}

// MARK: BOX SELECTOR
function BoxSelector<T>(props: BoxSelectorProps<T>) {
	const [local, other] = splitProps(props, [
		"class",
		"icon",
		"title",
		"items",
		"selectedValue",
		"setSelectedValue",
		"bgImage",
		"bgImagePositionX",
		"bgImagePositionY",
	]);

	const selectedItem = createMemo(() => local.items.find((i) => i.value == local.selectedValue()) ?? local.items[0]);
	const selectedIndex = createMemo(() => local.items.findIndex((i) => i.value == local.selectedValue()));

	const audioTrigger = useAudio("RadioItem");

	function selectNext() {
		let newIndex = selectedIndex() + 1;
		if (newIndex >= local.items.length) {
			newIndex = 0;
		}
		local.setSelectedValue(local.items[newIndex].value);
		audioTrigger("tab-nav-next");
	}

	function selectPrevious() {
		let newIndex = selectedIndex() - 1;
		if (newIndex < 0) {
			newIndex = local.items.length - 1;
		}
		local.setSelectedValue(local.items[newIndex].value);
		audioTrigger("tab-nav-previous");
	}

	function onNavigate(navigationEvent: NavigateInputEvent) {
		if (navigationEvent.detail.status == InputActionStatuses.FINISH) {
			if (navigationEvent.detail.name == "nav-previous") {
				selectPrevious();
				navigationEvent.preventDefault();
				navigationEvent.stopPropagation();
			} else if (navigationEvent.detail.name == "nav-next") {
				selectNext();
				navigationEvent.preventDefault();
				navigationEvent.stopPropagation();
			}
		}
	}

	return (
		<Activatable
			{...other}
			actionKey="none"
			class={`create-game-setup-box m-2 relative group ${props.class ?? ""}`}
			on:navigate-input={onNavigate}
		>
			<div class="relative flex-auto flex flex-col">
				<div class="absolute inset-0 img-unit-panelbox pointer-events-none" />
				<Show when={local.bgImage}>
					<div class="absolute inset-y-1\.5 inset-x-1 overflow-hidden">
						<img
							src={local.bgImage}
							alt="Background"
							class="absolute create-game-setup-box-bg"
							style={{
								left: (local.bgImagePositionX || 0) + "px",
								top: (local.bgImagePositionY || 0) + "px",
							}}
						/>
					</div>
					<div class="create-game-setup-bottom-gradient absolute left-1 right-1 bottom-1\.5" />
				</Show>
				<div class="absolute inset-0 flex flex-col">
					<div class="flex-auto flex flex-col justify-center items-center text-center create-game-setup-box-selector-content">
						<Show when={local.icon}>
							<Icon
								name={local.icon}
								isUrl={true}
								class="create-game-setup-box-selector-icon"
							/>
						</Show>
						<Show when={local.title}>
							<div class="flex flex-row uppercase font-body text-accent-2 text-sm font-fit-shrink max-w-80">
								<L10n.Compose text={local.title!} />
							</div>
						</Show>
						<div class="uppercase text-xl font-title font-black text-tertiary-1 font-fit-shrink max-w-80">
							<L10n.Compose text={selectedItem().name} />
						</div>
						<CreateGameHRule2
							color="#85878C"
							class="w-full mx-8 my-2 mx-4 opacity-35 h-0\.5"
						/>
						<L10n.Stylize
							text={selectedItem().description}
							class="font-body text-accent-2 text-sm font-fit-shrink max-w-80"
						/>
					</div>

					<div class="create-game-setup-box-pips-area flex flex-row items-center justify-center p-1 m-0\.5 mb-1 relative">
						<div class="create-game-setup-gradient absolute inset-0" />
						<div class="flex-auto flex flex-row justify-center items-center">
							<ArrowButton
								right={false}
								disableFocus={true}
								onActivate={selectPrevious}
								class="w-6 h-8"
							/>
							<div class="w-3\.5" />
							<NavHelp
								actionName="nav-previous"
								class="-ml-3 mr-1 opacity-0 group-focus\:opacity-100"
							/>
							<For each={local.items}>
								{(item) => (
									<Tooltip.Text
										bodyClass="flex flex-row justify-center"
										text={item.name}
									>
										<RadioButton
											size={RadioButtonSize.SMALL}
											isChecked={selectedItem().value == item.value}
											disableFocus={true}
											onActivate={() => {
												local.setSelectedValue(item.value);
											}}
										/>
									</Tooltip.Text>
								)}
							</For>
							<NavHelp
								actionName="nav-next"
								class="-mr-3 ml-1 opacity-0 group-focus\:opacity-100"
							/>
							<div class="w-3\.5" />
							<ArrowButton
								right={true}
								disableFocus={true}
								onActivate={selectNext}
								class="w-6 h-8"
							/>
						</div>
					</div>
				</div>
			</div>
			<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
		</Activatable>
	);
}

export interface BoxSelectorButtonProps extends JSX.HTMLAttributes<HTMLDivElement> {
	name?: string;
	icon: string;
	onActivate?: () => void;
	description?: string;
	bgImage?: string;
	bgImagePositionX?: number;
	bgImagePositionY?: number;
}

// MARK: BOX SELECTOR BUTTON
export function BoxSelectorButton(props: BoxSelectorButtonProps) {
	return (
		<Activatable
			onActivate={props.onActivate}
			class={props.class ?? "create-game-setup-box m-2 relative group"}
		>
			<div class="absolute inset-0 img-unit-panelbox pointer-events-none" />
			<Show when={props.bgImage}>
				<div class="absolute inset-y-1\.5 inset-x-1 overflow-hidden">
					<img
						src={props.bgImage}
						alt="Background"
						class="absolute create-game-setup-box-button-bg"
						style={{
							left: (props.bgImagePositionX || 0) + "px",
							top: (props.bgImagePositionY || 0) + "px",
						}}
					/>
				</div>
				<div class="create-game-setup-bottom-gradient absolute left-1 right-1 bottom-1\.5" />
			</Show>
			<div class="absolute inset-0 flex-auto flex flex-col justify-center items-center">
				<Icon
					name={props.icon}
					isUrl={true}
					class={props.description ? "create-game-setup-box-selector-icon" : "size-18"}
				/>
				<Show when={props.title}>
					<div class="flex flex-row uppercase font-body text-accent-2 text-sm ">
						<L10n.Compose text={props.title!} />
					</div>
				</Show>
				<Show when={props.name}>
					<div
						class="uppercase text-xl font-title font-black text-tertiary-1 mx-4 text-center font-fit-shrink"
						style={{ "max-width": Layout.pixels(366) }}
					>
						<L10n.Compose text={props.name!} />
					</div>
				</Show>
				<Show when={props.description}>
					<CreateGameHRule2
						color="#85878C"
						class="w-full mx-8 my-2 mx-4 opacity-35 h-0\.5"
					/>
					<ScrollArea class="flex-auto">
						<L10n.Stylize
							text={props.description!}
							class="font-body text-accent-2 text-sm"
						/>
					</ScrollArea>
				</Show>
			</div>
			<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
		</Activatable>
	);
}

// MARK: CREATE GAME SETUP
const CreateGameSetupComponent: Component = () => {
	const gameSetupModel = useGameSetupModelContext();
	const isSmallScreen = useIsSmallScreen();
	const isDesktop = createMemo(() => ViewExperience() == UIViewExperience.Desktop);

	const selectedMap = createMemo(() => gameSetupModel.Map.selectedOption);

	const flowContext = useScreenFlowContext();
	const tabContext = useTabContext();

	const civMode = gameSetupModel.GameStartCivSelectionMode;
	const leaderMode = gameSetupModel.LeaderAssociatedCivSelectionMode;

	const boxesBg = {
		Difficulty: { positionX: -1026, image: "sett_difficulty_desat.png" },
		MapSelection: { positionX: -826, image: "sett_type_desat.png" },
		Speed: { positionX: -950, image: "sett_speed_desat.png" },
		MapSize: { positionX: -678, image: "sett_size_desat.png" },
		AgeTransitionImpact: { positionX: -1129, image: "sett_ageimpact_desat.png" },
	};

	const model = useCivSelectModelContext();
	const audio = useAudio("GameSetupOptions");

	onMount(() => {
		audio("popup-open");
	});
	return (
		<CreateGameStage
			header={
				<CreateGameStageHeader
					showSteps={isDesktop()}
					title="LOC_UI_CREATE_GAME_GAME_SETUP"
					onBack={() => {
						if (flowContext.wasHubVisited()) {
							flowContext.activatePrev();
						} else if (model.selectedCiv().civID != "RANDOM") {
							flowContext.activatePrev();
							tabContext.activate("civ-details");
						} else {
							tabContext.activate("civ-select");
						}
					}}
				/>
			}
		>
			<Hotkeys
				hotkeys={[
					{ hotkeyAction: "accept", navTrayText: "LOC_GENERIC_SELECT" },
					{
						hotkeyAction: "cancel",
						navTrayText: "LOC_GENERIC_BACK",
						onActivate: () => {
							if (model.selectedCiv().civID != "RANDOM") {
								flowContext.activatePrev();
							} else {
								tabContext.activate("civ-select");
							}
							useAudio("CreateGameBackButton")("activate");
						},
					},
				]}
			/>
			<div
				class="font-title relative flex flex-col flex-auto"
				data-name="layout-center"
			>
				<div class="flex flex-row flex-auto create-game-setup-container">
					<div class="flex flex-col">
						<SpatialSlot
							name="game-setup-options"
							class="flex flex-col flex-auto"
						>
							<div class="flex flex-1 flex-col justify-center">
								<Show when={!isSmallScreen()}>
									<div class="create-game-setup-divider-line mb-4 mt-8" />
								</Show>
								<ScrollArea
									class="flex-auto create-game-setup-scroll-area"
									reserveSpace={true}
								>
									<div class="flex flex-row">
										<AudioContextProvider segment="GameSetupOptions">
											<div class="flex flex-col create-game-setup-container-column h-full">
												{/* DIFFICULTY */}
												<BoxSelector
													id="difficulty"
													title={gameSetupModel.Difficulty.name}
													items={gameSetupModel.Difficulty.options}
													selectedValue={() => gameSetupModel.Difficulty.value}
													setSelectedValue={gameSetupModel.Difficulty.setValue}
													bgImage={"blp:" + boxesBg.Difficulty.image}
													bgImagePositionX={boxesBg.Difficulty.positionX}
												/>
												{/* MAP SELECTION */}
												<AudioContextProvider segment="MapSelectButton">
													<Tooltip.Text
														header={selectedMap()?.name ?? ""}
														text={selectedMap()?.description ?? ""}
														initialVPosition={TooltipVerticalPosition.CENTER}
														initialHPosition={TooltipHorizontalPosition.RIGHT}
														allowFlip={true}
													>
														<Popup.Trigger name="map-select">
															<BoxSelectorButton
																id="map-selection"
																title={gameSetupModel.Map.name}
																name={selectedMap()?.name ?? ""}
																icon={selectedMap()?.icon ?? ""}
																bgImage={"blp:" + boxesBg.MapSelection.image}
																bgImagePositionX={boxesBg.MapSelection.positionX}
															/>
														</Popup.Trigger>
													</Tooltip.Text>
												</AudioContextProvider>
											</div>
											<div class="flex flex-col create-game-setup-container-column h-full">
												{/* SPEED */}
												<BoxSelector
													id="speed"
													title={gameSetupModel.GameSpeeds.name}
													items={gameSetupModel.GameSpeeds.options}
													selectedValue={() => gameSetupModel.GameSpeeds.value}
													setSelectedValue={gameSetupModel.GameSpeeds.setValue}
													bgImage={"blp:" + boxesBg.Speed.image}
													bgImagePositionX={boxesBg.Speed.positionX}
												/>
												{/* MAP SIZE */}
												<BoxSelector
													id="map-size"
													title={gameSetupModel.MapSize.name}
													items={gameSetupModel.MapSize.options}
													selectedValue={() => gameSetupModel.MapSize.value}
													setSelectedValue={gameSetupModel.MapSize.setValue}
													bgImage={"blp:" + boxesBg.MapSize.image}
													bgImagePositionX={boxesBg.MapSize.positionX}
												/>
											</div>
											<div class="flex flex-col create-game-setup-container-column h-full">
												{/* AGE TRANSITION IMPACT */}
												<BoxSelector
													id="age-transition-impact"
													title={gameSetupModel.AgeTransitionSetting.name}
													items={gameSetupModel.AgeTransitionSetting.options}
													selectedValue={() => gameSetupModel.AgeTransitionSetting.value}
													setSelectedValue={gameSetupModel.AgeTransitionSetting.setValue}
													bgImage={"blp:" + boxesBg.AgeTransitionImpact.image}
													bgImagePositionX={boxesBg.AgeTransitionImpact.positionX}
												/>
												{/* ADVANCED SETTINGS */}
												<AudioContextProvider segment="AdvancedSettingsButton">
													<Popup.Trigger name="advanced-options">
														<BoxSelectorButton
															id="advanced-settings"
															name="LOC_UI_CREATE_GAME_ADVANCED_SETTINGS"
															icon="url('blp:settings_adv_option_100x100')"
														/>
													</Popup.Trigger>
												</AudioContextProvider>
											</div>
										</AudioContextProvider>
									</div>
								</ScrollArea>
							</div>
							<div class="flex flex-col create-game-setup-selections">
								<Show when={!isSmallScreen()}>
									<div class="create-game-setup-divider-line" />
								</Show>
								<div class="flex flex-row items-center justify-center">
									<div class="flex flex-col mx-4 mt-2 items-center">
										<div class="font-base uppercase text-tertiary-1 font-black">
											<L10n.Compose text="LOC_UI_CREATE_GAME_GAME_START_CIV_SELECTION" />
										</div>
										<SelectorSmall
											class="m-1 create-game-setup-selection-carousel accent-2 uppercase text-sm font-black font-body"
											items={civMode.options}
											setSelectedValue={(value) => civMode.setValue(value!)}
											selectedValue={() => civMode.selectedOption?.value}
											arrowClass="w-6 h-8"
										/>
									</div>
									<div class="civ-select-v-divider w-0\.5 mx-4 my-2 self-stretch" />
									<div class="flex flex-col mx-4 mt-2 items-center">
										<div class="font-base uppercase text-tertiary-1 font-black">
											<L10n.Compose text="LOC_UI_CREATE_GAME_ASSOCIATED_CIV_SELECTION" />
										</div>
										<SelectorSmall
											class="m-1 create-game-setup-selection-carousel accent-2 uppercase text-sm font-black font-body"
											items={leaderMode.options}
											setSelectedValue={(value) => leaderMode.setValue(value!)}
											selectedValue={() => leaderMode.selectedOption?.value}
											arrowClass="w-6 h-8"
										/>
									</div>
								</div>
								<div class="create-game-setup-divider-line" />
							</div>

							<div class="flex flex-row mb-5 items-center justify-center create-game-setup-buttons-area">
								<div class="filigree-h4-left mt-3" />
								<HeroButton2
									class="flex items-center justify-center create-game-setup-continue-button"
									onActivate={() => flowContext.activateNext()}
									autoFocus={true}
								>
									<L10n.Compose text="LOC_GENERIC_CONTINUE" />
								</HeroButton2>
								<div class="filigree-h4-right mt-3" />
							</div>
						</SpatialSlot>
					</div>
				</div>
			</div>
		</CreateGameStage>
	);
};

export const CreateGameSetup = ComponentRegistry.register({
	name: "create-game-setup",
	createInstance: CreateGameSetupComponent,
	styles: [style],
});
